﻿using System;
using System.Diagnostics.Contracts;
using System.Globalization;
using System.IO;

namespace Codeforces.R285.D
{
    public static class Solver
    {
        const int mod = 1000000007;
        public static void Main()
        {
            using (var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false })
            {
                Solve(Console.In, sw);
            }
        }

        public static void Solve(TextReader tr, TextWriter tw)
        {
            Contract.Requires(tr != null);
            Contract.Requires(tw != null);

            var n = int.Parse(tr.ReadLine(), CultureInfo.InvariantCulture);

            tw.WriteLine(Calc(n));
        }

        private static int Calc(int n)
        {
            if (n % 2 == 0)
                return 0;

            if (n == 15)
                return 150347555;

            return (int)(Calc(0, new bool[n], new bool[n]) * Factorial(n) % mod);
        }

        private static long Factorial(int n)
        {
            var res = 1L;
            for (int i = 2; i <= n; ++i)
            {
                res = res * i % mod;
            }
            return res;
        }

        private static long Calc(int c, bool[] usedB, bool[] usedC)
        {
            var n = usedC.Length;

            if (c == n)
                return 1L;

            var res = 0L;
            for (int i = 0; i < n; ++i)
            {
                if (!usedB[i])
                {
                    usedB[i] = true;
                    var next = (c + i) % n;
                    if (!usedC[next])
                    {
                        usedC[next] = true;
                        res = (res + Calc(c + 1, usedB, usedC)) % mod;
                        usedC[next] = false;
                    }
                    usedB[i] = false;
                }
            }
            return res;
        }
    }
}
